  /** Short species name for compact labels ("Zebra", "Twin-flagged"). */
  JT.shortName = (S) => S ? S.name.replace(/ (Jumper|Spider|Morph)$/, '') : '';
  /** Which jumpers a piece camouflages, as a readable list. */
  JT.blendNames = (d) => (d && d.blend || []).map(id => JT.shortName(JT.SPECIES_BY_ID && JT.SPECIES_BY_ID[id])).filter(Boolean);
  JT.DECOR_BY_ID = {}; JT.DECOR.forEach(d => JT.DECOR_BY_ID[d.id] = d);
