  JT.WALL_TANK_KITS = {
    standard: ['wk_stub', 'wk_flowerpocket'], arboreal: ['wk_hangvine', 'wk_brompocket'], cube: ['wk_hangvine', 'wk_flowerpocket'], jar: ['wk_hangvine', 'wk_brompocket'], tower: ['wk_hangvine', 'wk_brompocket'],
    wide: ['wk_longbranch', 'wk_ledgerun'], panoramic: ['wk_longbranch', 'wk_ledgerun'], nano: ['wk_tinyledge', 'wk_twig', 'wk_minimoss'], breeder: ['wk_tinyledge', 'wk_twig', 'wk_minimoss'],
  };
  /** The free pieces on offer for a habitat's wall: its theme kit first, then the tank-type extras (no duplicates). */
  JT.wallKit = function (hab) {
    const w = hab && hab.backWall && hab.backWall(); if (!w) return [];
    const out = []; for (const id of (JT.WALL_KITS[w.type] || []).concat(JT.WALL_TANK_KITS[hab.data.type] || [])) if (JT.DECOR_BY_ID[id] && !out.includes(id)) out.push(id);
    return out;
  };

